from typing import Any, Optional
from pydantic import BaseModel, Field
from app.dto.enums import GuardrailAction, Severity


class GuardrailViolation(BaseModel):
    """Detailed violation record generated by a guardrail check."""
    guardrail_name: str = Field(..., description="Name of the guardrail reporting violation")
    message: str = Field(..., description="Human readable description of the violation")
    severity: Severity = Field(default=Severity.HIGH, description="Severity level")
    details: dict[str, Any] = Field(default_factory=dict, description="Additional context or metadata regarding the violation")


class GuardrailResult(BaseModel):
    """Execution result of a single guardrail strategy."""
    guardrail_name: str = Field(..., description="Name of the guardrail strategy")
    action: GuardrailAction = Field(..., description="Decision made by guardrail: ALLOW, BLOCK, or WARNING")
    sanitized_content: Optional[Any] = Field(default=None, description="Sanitized/masked request or response payload if applicable")
    score: float = Field(default=1.0, ge=0.0, le=1.0, description="Confidence or compliance score (0.0 to 1.0)")
    violations: list[GuardrailViolation] = Field(default_factory=list, description="List of detected violations")
    execution_time_ms: float = Field(default=0.0, description="Time taken to run this guardrail in milliseconds")


class PipelineResult(BaseModel):
    """Consolidated result of a complete guardrail pipeline run."""
    is_allowed: bool = Field(..., description="True if prompt/response is allowed to proceed")
    action: GuardrailAction = Field(..., description="Final overall decision (ALLOW, BLOCK, WARNING)")
    violations: list[GuardrailViolation] = Field(default_factory=list, description="All accumulated violations")
    sanitized_request: Optional[Any] = Field(default=None, description="Cleaned request payload for Input Pipeline")
    sanitized_response: Optional[Any] = Field(default=None, description="Cleaned response payload for Output Pipeline")
    total_execution_time_ms: float = Field(default=0.0, description="Total execution time of the pipeline in milliseconds")
    guardrail_results: list[GuardrailResult] = Field(default_factory=list, description="Individual results for executed guardrails")
